import {DEFAULT_POLICY} from './owner-policy.mjs';
export const EDITOR_RUN='00000000-0000-4000-8000-000000000001';
export function createOwnerWorkspace({api,state,render,esc,money,time,head,refresh}){
 let catalog=null,entries=[],active=[],settings={},loading=false,error='',chat=null,chatAfter=0,chatKey='',chatBusy=false,chatNew=false,historyLimit=12,ruleFilter='all',ruleMode='write';
 const drafts=new Map(),keyFor=()=>location.hash.split('/').slice(1).join('/');
 const call=(action,p={})=>api('workspace',{action,...p});
 const read=(action,p={})=>api('workspace?'+new URLSearchParams({action,...p}));
 function saveDraft(id){const el=document.getElementById(id);if(el)drafts.set(id,el.value);}
 function applyDrafts(){for(const [id,value] of drafts){const el=document.getElementById(id);if(el)el.value=value;}}
 async function loadRules(){if(loading)return;loading=true;error='';try{if(!catalog){const r=await fetch('/data/rule-catalog.json',{cache:'no-cache'});if(!r.ok)throw Error('Instruction catalog unavailable');catalog=await r.json();}let after=0,all=[];for(let page=0;page<1000;page++){const d=await read('instructions',{after});all.push(...d.entries);active=d.active;settings={...DEFAULT_POLICY,...d.settings};if(d.entries.length<250)break;after=d.entries.at(-1).id;}entries=all;}catch(e){error=e.message;}finally{loading=false;render();applyDrafts();}}
 const ownEntry=e=>`<article class="instruction" data-anchor="instruction-${e.id}"><header><strong>#${e.id} · ${esc(e.author)}</strong><span class="badge">${esc(e.action==='apply'?(active.some(a=>a.id===e.id)?'Active':'Retired'):(e.data?.historyImport?'Historical':e.action))}</span><small>${time(e.created_at)} · ${e.scope==='all'?'Both agents':esc(e.scope)}</small></header><p class="rule-text">${esc(e.body)}</p>${e.data?.text?`<details data-key="import-${e.id}"><summary>Read the exact original source</summary><pre class="source-code">${esc(e.data.text)}</pre></details>`:''}${e.action==='settings'?`<details data-key="setting-${e.id}"><summary>Exact before / after settings</summary><pre>${esc(JSON.stringify(e.data,null,2))}</pre></details>`:''}${e.action==='apply'&&active.some(a=>a.id===e.id)?`<button class="text-button" data-retire-rule="${e.id}">Retire this instruction…</button>`:''}</article>`;
 function policyForm(){const p={...DEFAULT_POLICY,...settings};return `<details data-key="technical-settings"><summary>Technical trading settings you control</summary><p>These settings change code-enforced entry checks. Written instructions alone cannot silently change them. Existing investments keep their recorded exit plans. Defaults below match the existing experiment.</p><form id="policy-form"><div class="control-grid"><label><input id="policy-alpha15Only" type="checkbox" ${p.alpha15Only?'checked':''}> AlphaBot only considers BTC 15-minute markets</label><label><input id="policy-requireExitPlan" type="checkbox" ${p.requireExitPlan?'checked':''}> Require a numeric stop, profit target and time exit</label><label><input id="policy-paceResearch" type="checkbox" ${p.paceResearch?'checked':''}> Spread the existing AI allowance across the day</label>${[['minimumEdge','Minimum estimated edge above costs (%)',p.minimumEdge*100,0,100,'0.1'],['minimumHistory','Minimum real observations',p.minimumHistory,0,100,1],['maximumPositions','Maximum open investments',p.maximumPositions,1,100,1],['maximumHorizonDays','Maximum settlement horizon (days)',p.maximumHorizonDays,1,30,1],['alphaCloseMinutes','AlphaBot entry cutoff before close (minutes)',p.alphaCloseMinutes,0,14,1]].map(([k,label,value,min,max,step])=>`<label>${label}<input id="policy-${k}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`).join('')}</div><label>Reason<input id="policy-reason" maxlength="500" placeholder="Why are you changing these settings?"></label><button type="submit" class="primary">Review settings…</button></form><p class="small">Fake-money execution, accurate accounting, verified quotes and existing spending limits remain operating controls. Every setting applied here is appended to the history.</p></details>`;}
 function controlText(c){const p={...DEFAULT_POLICY,...settings};if(c.id==='control-1')return `Current setting: AlphaBot ${p.alpha15Only?'BTC 15-minute only':'any supplied market'}; entry cutoff ${p.alphaCloseMinutes} minute(s) before close. Latest settlement within ${p.maximumHorizonDays} days. Both agents use the same bounded market discovery described in the original source.`;if(c.id==='control-2')return `Current setting: ${p.minimumHistory} real observations; at least ${(p.minimumEdge*100).toFixed(1)} percentage points estimated edge after fees; maximum ${p.maximumPositions} open investments; numeric exit plan ${p.requireExitPlan?'required':'optional'}. These values change only when you apply the settings form.`;return c.text;}
 function rulesPage(){if(!catalog&&!loading&&!error)void loadRules();return `<section class="panel"><h2>Your instructions. Full recorded history.</h2><div class="actions"><button data-jump="instruction-form">Write an instruction ↓</button><button data-jump="funding-form">Give paper money ↓</button></div><p>You control new instructions. Drafting or discussing one does not apply it.</p><p class="history-note">${esc(catalog?.coverage||'Loading the instruction inventory…')}</p><button data-rules-reload>Refresh history</button>${error?`<p role="alert">${esc(error)}</p>`:''}<div class="history-filter">${[['all','Full history'],['active','Active now'],['owner','Your entries']].map(([v,label])=>`<button data-rule-filter="${v}" aria-pressed="${ruleFilter===v}">${label}</button>`).join('')}</div>${ruleFilter!=='owner'?(catalog?.controls||[]).map(c=>`<article class="instruction" data-anchor="${c.id}"><header><strong>${esc(c.title)}</strong><span class="badge">${esc(c.category)}</span><small>Source: ${esc(c.source)}</small></header><p>${esc(controlText(c))}</p><details data-key="source-${c.id}"><summary>Read exact current source</summary><pre class="source-code">${esc(catalog.current.find(x=>x.source===c.source)?.text||'See current source inventory below.')}</pre></details></article>`).join(''):''}${ruleFilter==='all'?`<details data-key="historical-prompts"><summary>Historical prompts, restrictions and original source (${catalog?.history.length||0} versions)</summary><p class="small">Commit dates show when the source was recorded, not a reconstructed date of owner approval. Historical copies do not become active again.</p>${(catalog?.history||[]).slice(0,historyLimit).map((e,i)=>`<article class="instruction" data-anchor="history-${e.id}"><strong>Historical ${i+1} · ${esc(e.source)}</strong><small>${time(e.at)} · ${esc(e.commit.slice(0,7))}</small><p>${esc(e.title)}</p><details data-key="historical-${e.id}"><summary>Read original wording / behavior</summary><pre class="source-code">${esc(e.text)}</pre></details></article>`).join('')}${historyLimit<(catalog?.history.length||0)?'<button data-rule-older>Show more historical versions</button>':''}</details><details data-key="current-source"><summary>All current prompts and operating checks (${catalog?.current.length||0} files)</summary>${(catalog?.current||[]).map(e=>`<details data-key="file-${e.sha256}"><summary>${esc(e.source)}</summary><pre class="source-code">${esc(e.text)}</pre></details>`).join('')}</details>`:''}<h3>Chronological instruction comments</h3>${entries.filter(e=>ruleFilter==='owner'?e.author==='Owner':ruleFilter!=='active'||active.some(a=>a.id===e.id)).map(ownEntry).join('')||'<p>No owner instruction entries in this view yet.</p>'}${policyForm()}</section>${fundingForm()}<section class="panel composer"><h2>Add your next instruction</h2><div class="history-filter"><button data-rule-mode="write" aria-pressed="${ruleMode==='write'}">Write directly</button><button data-rule-mode="talk" aria-pressed="${ruleMode==='talk'}">Talk it through</button></div>${ruleMode==='talk'?`<p>Discuss a draft with the instruction editor. This does not change the agents’ instructions.</p><a class="icon-button" href="#chat/rules/${EDITOR_RUN}">Open saved instruction discussion →</a>`:''}<form id="instruction-form"><label>Applies to<select id="instruction-target"><option value="all">Both agents</option><option value="A">AlphaBot</option><option value="B">Beta</option></select></label><label>Your wording<textarea id="instruction-text" maxlength="4000" placeholder="Type or dictate your instruction…" required>${esc(drafts.get('instruction-text')||'')}</textarea></label><div class="actions"><button type="button" data-dictate="instruction-text">🎙 Dictate</button><button type="submit" class="primary">Review & apply…</button></div><p class="speech-status" id="speech-status" role="status"></p></form><p class="small">New instructions are added as the next entry; earlier entries remain. Only pressing Apply in the confirmation changes future decisions.</p></section>`;}
 function fundingForm(){return `<section class="panel composer"><h2>Give paper money</h2><p>Give an agent cash to trade. Your contribution stays separate from its trading profit.</p><form id="funding-form"><label>Give this amount ($)<input id="funding-amount" type="number" min="0.01" step="0.01" placeholder="100.00" required></label><label>To<select id="funding-agent">${state().agents.map(a=>`<option value="${a.id}">${esc(a.appId)} · ${esc(a.displayName)}</option>`).join('')}</select></label><label>Funding type<select id="funding-kind"><option value="grant">Give paper cash — no repayment</option><option value="loan">Owner-initiated paper loan — existing bank terms</option></select></label><label>Reason (optional)<input id="funding-reason" maxlength="800" placeholder="Extra capital for testing"></label><button class="primary" type="submit">Review funding…</button></form><p class="small">A loan still has the existing eligibility, bank cash and annual interest limits. This only changes fake trading cash, never your OpenAI credits or spending limits.</p></section>`;}
 function getTarget(){const parts=location.hash.slice(1).split('/');if(parts[1]==='rules')return {id:'rules',runId:EDITOR_RUN,displayName:'Instruction discussion',appId:'Rules editor'};const a=state().agents.find(a=>a.id===(parts[1]||'A'));return {id:parts[1]||a?.id||'A',runId:parts[2]||a?.runId,displayName:a?.displayName,appId:a?.appId};}
 async function loadChat({more=false,automatic=false}={}){if(chatBusy)return;const t=getTarget(),key=t.id+'/'+t.runId;chatBusy=true;try{if(key!==chatKey){chat=null;chatAfter=0;chatKey=key;}const d=await read('messages',{agent:t.id,runId:t.runId,...(more?{before:chat?.messages[0]?.id||0}:{})});const prior=chat?.messages||[],combined=new Map((more?[...d.messages,...prior]:[...prior,...d.messages]).map(m=>[m.id,m])),messages=[...combined.values()].sort((a,b)=>a.id-b.id);const next={...d,messages};if(more&&d.messages.length)chatAfter=d.messages.at(-1).id;else if(!more)chatAfter=d.messages.at(-1)?.id||0;next.more=more?d.hasOlder:(chat?.more??d.hasOlder);if(automatic&&document.activeElement?.matches('textarea,input,select')){chatNew=true;return;}chat=next;chatNew=false;error='';render();applyDrafts();}catch(e){error=e.message;if(!automatic)render();}finally{chatBusy=false;}}
 function chatPage(){const t=getTarget(),key=t.id+'/'+t.runId;if(chatKey!==key&&!chatBusy){chat=null;void loadChat();}const a=chat?.agent||t,readOnly=chat?.readOnly;return `<section class="panel">${t.id==='rules'?'<h2>Instruction discussion</h2>':head(a)}<p>One saved conversation for this agent run. All messages stay with its retired profile.</p><div class="agent-jump">${t.id==='rules'?'<a href="#rules">← Rules & instructions</a>':`<a href="#profiles/${esc(t.id)}">View profile</a><a href="#archives">Past agents</a>`}</div><p class="small">Chat replies use the existing AI allowance. Chat cannot trade, lend or apply instructions. Full history is stored; replies use up to the latest 30 messages.</p></section><section class="chat-list" id="chat-messages">${error?`<p role="alert">${esc(error)}</p>`:''}${(chat?.messages||[]).map(m=>`<article class="chat-message ${m.role}" data-anchor="message-${m.id}"><strong>${m.role==='owner'?'You':esc(a.displayName||'Agent')}</strong><small>${time(m.created_at)} · ${esc(m.status)}</small><p class="rule-text">${esc(m.body||'Reply queued…')}</p>${!readOnly&&m.role==='assistant'&&['pending','waiting'].includes(m.status)?`<button class="text-button" data-cancel-message="${m.id}">Cancel queued reply</button>`:''}${m.role==='owner'?`<button class="text-button" data-message-instruction="${m.id}">Use this wording as an instruction…</button>`:''}</article>`).join('')||'<p>No messages loaded yet. Start a conversation below.</p>'}${chat?.more?'<button data-chat-more>Load older messages</button>':''}${chatNew?'<button data-chat-refresh>New reply available — show it</button>':'<button data-chat-refresh>Refresh conversation</button>'}</section>${readOnly?'<section class="panel"><strong>Archived conversation · Read only</strong><p>These messages belong to this retired agent. A replacement starts its own conversation.</p></section>':`<section class="panel composer"><form id="chat-form"><label>Message to ${esc(a.displayName||'agent')}<textarea id="chat-text" maxlength="4000" required placeholder="Ask a question or discuss your next instruction…">${esc(drafts.get('chat-text:'+key)||'')}</textarea></label><div class="actions"><button type="button" data-dictate="chat-text">🎙 Dictate</button><button type="submit" class="primary" ${chat?.messages.some(m=>['pending','processing','waiting'].includes(m.status))?'disabled':''}>Send message</button></div><p class="speech-status" id="speech-status" role="status"></p></form></section>`}`;}
 function profileTools(a){return `<div class="actions"><a class="icon-button" href="#chat/${a.id}/${esc(a.runId)}">Open saved chat</a><button class="like" data-like="${a.id}" aria-pressed="${a.ownerAppreciation?.liked===true}">👍 ${a.ownerAppreciation?.liked?'Liked':'Like agent'}</button></div><p class="small">Profile appreciation is shown to this agent on later decisions; it grants no money or permissions.</p>`;}
 function confirm(title,body,callback){const dialog=document.createElement('dialog');dialog.className='panel';dialog.innerHTML=`<h2>${esc(title)}</h2><div class="rule-text">${esc(body)}</div><div class="actions"><button data-cancel>Cancel</button><button class="primary" data-apply>Apply</button></div>`;document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('[data-apply]').onclick=async()=>{dialog.querySelector('[data-apply]').disabled=true;try{await callback();dialog.close();}catch(e){dialog.querySelector('[data-apply]').disabled=false;let alert=dialog.querySelector('[role=alert]');if(!alert){alert=document.createElement('p');alert.setAttribute('role','alert');dialog.append(alert);}alert.textContent=e.message;}};dialog.showModal();}
 let recognition=null;
 function dictate(id,button){const field=document.getElementById(id),status=document.getElementById('speech-status'),Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(recognition){recognition.stop();recognition=null;button.textContent='🎙 Dictate';return;}if(!Speech){field.focus();status.textContent='This browser does not expose dictation. Use the microphone on your phone’s keyboard, or type here. Nothing is sent automatically.';return;}const before=field.value;recognition=new Speech();recognition.lang='en-US';recognition.interimResults=true;recognition.continuous=false;recognition.onresult=e=>{field.value=before+(before?' ':'')+[...e.results].map(r=>r[0].transcript).join(' ');field.dispatchEvent(new Event('input',{bubbles:true}));};recognition.onerror=e=>{status.textContent='Dictation '+e.error+'. You can still type or use keyboard dictation.';};recognition.onend=()=>{recognition=null;button.textContent='🎙 Dictate';status.textContent='Dictation stopped. Review the text before sending or applying.';};recognition.start();button.textContent='■ Stop dictation';status.textContent='Listening through your browser’s speech service… Review the text before sending.';}
 function install(root){root.addEventListener('input',e=>{if(e.target.id==='instruction-text')saveDraft('instruction-text');if(e.target.id==='chat-text')drafts.set('chat-text:'+keyFor(),e.target.value);});root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.jump){document.getElementById(b.dataset.jump)?.scrollIntoView({block:'start'});return;}if(b.dataset.ruleFilter){ruleFilter=b.dataset.ruleFilter;render();applyDrafts();}if(b.dataset.ruleMode){saveDraft('instruction-text');ruleMode=b.dataset.ruleMode;render();applyDrafts();}if(b.hasAttribute('data-rules-reload'))await loadRules();if(b.hasAttribute('data-rule-older')){historyLimit+=12;render();}if(b.dataset.retireRule){const entry=entries.find(x=>x.id===Number(b.dataset.retireRule));confirm('Retire this instruction?',entry.body,async()=>{await call('instruction-retire',{id:entry.id,scope:entry.scope,text:'Owner retired instruction #'+entry.id,requestId:crypto.randomUUID(),confirmed:true});await loadRules();await refresh(true);});}if(b.dataset.like){const a=state().agents.find(a=>a.id===b.dataset.like);b.disabled=true;await call('like',{agent:a.id,runId:a.runId,liked:!a.ownerAppreciation?.liked});await refresh(true);}if(b.hasAttribute('data-chat-refresh'))await loadChat();if(b.hasAttribute('data-chat-more'))await loadChat({more:true});if(b.dataset.cancelMessage){const t=getTarget();await call('message-cancel',{agent:t.id,runId:t.runId,id:Number(b.dataset.cancelMessage)});await loadChat();}if(b.dataset.messageInstruction){const m=chat.messages.find(m=>m.id===Number(b.dataset.messageInstruction));drafts.set('instruction-text',m.body);location.hash='rules';}if(b.dataset.dictate)dictate(b.dataset.dictate,b);}catch(e){error=e.message;document.getElementById('message').textContent=e.message;b.disabled=false;}});
 root.addEventListener('submit',async e=>{if(!['instruction-form','chat-form','policy-form','funding-form'].includes(e.target.id))return;e.preventDefault();if(e.target.id==='instruction-form'){const text=document.getElementById('instruction-text').value.trim(),scope=document.getElementById('instruction-target').value;if(!text)return;const requestId=crypto.randomUUID();confirm('Apply this exact instruction?',`Target: ${scope==='all'?'Both agents':scope}\n\n${text}\n\nThis affects future decisions. Older instructions remain in history.`,async()=>{await call('instruction-apply',{text,scope,requestId,confirmed:true});drafts.delete('instruction-text');document.getElementById('instruction-text').value='';await loadRules();await refresh(true);});}
 if(e.target.id==='policy-form'){const next={};for(const [k,v] of Object.entries(DEFAULT_POLICY)){const el=document.getElementById('policy-'+k);next[k]=typeof v==='boolean'?el.checked:Number(el.value);}next.minimumEdge/=100;const reason=document.getElementById('policy-reason').value;confirm('Apply these trading settings?',JSON.stringify(next,null,2),async()=>{await call('settings',{settings:next,scope:'all',text:reason,requestId:crypto.randomUUID(),confirmed:true});await loadRules();await refresh(true);});}
 if(e.target.id==='funding-form'){const agent=state().agents.find(a=>a.id===document.getElementById('funding-agent').value),amount=Math.round(Number(document.getElementById('funding-amount').value)*100),kind=document.getElementById('funding-kind').value,reason=document.getElementById('funding-reason').value,requestId=crypto.randomUUID();confirm(kind==='loan'?'Approve this paper loan?':'Give this paper money?',`${money(amount)} to ${agent.appId} · ${agent.displayName}\n${kind==='loan'?'Existing bank interest and eligibility apply.':'This is owner capital, not trading profit.'}\n${reason}`,async()=>{await api('control',{action:'owner-funding',agent:agent.id,expectedRunId:agent.runId,amount,kind,reason,requestId,confirmed:true});await refresh(true);});}
 if(e.target.id==='chat-form'){const t=getTarget(),text=document.getElementById('chat-text').value.trim();if(!text)return;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await call('message-send',{agent:t.id,runId:t.runId,text,requestId:crypto.randomUUID()});drafts.delete('chat-text:'+keyFor());document.getElementById('chat-text').value='';await loadChat();}catch(e){button.disabled=false;document.getElementById('message').textContent=e.message;}}});}
 return {rulesPage,chatPage,profileTools,install,loadRules,afterRender:applyDrafts,poll:async()=>{if(location.hash.startsWith('#chat')&&chat?.messages.some(m=>['pending','processing','waiting'].includes(m.status)))await loadChat({automatic:true});}};
}
